// hooks and interceptors per client, for fast access.
type (
	hooks struct {
		AccessToken, AdminGrant, Agent, AgentGrant, AgentInstallation, AgentToken, App,
		AuditEvent, AuthorizationCode, Challenge, Connection, ExternalIdentity, Flow,
		IdempotencyReceipt, Identifier, ManagementSession, OAuthClient, OAuthConsent,
		Operator, OutboxMessage, Passkey, PasskeyCeremony, PlatformReceipt,
		RefreshFamily, RefreshToken, Session, SigningKey, User []ent.Hook
	}
	inters struct {
		AccessToken, AdminGrant, Agent, AgentGrant, AgentInstallation, AgentToken, App,
		AuditEvent, AuthorizationCode, Challenge, Connection, ExternalIdentity, Flow,
		IdempotencyReceipt, Identifier, ManagementSession, OAuthClient, OAuthConsent,
		Operator, OutboxMessage, Passkey, PasskeyCeremony, PlatformReceipt,
		RefreshFamily, RefreshToken, Session, SigningKey, User []ent.Interceptor
	}
)
